# Break My Fix finding 2, generated by Tracefix: Env.db_url returns a wrong value.
# Property (issue): env.db_url passes extra_options through so they appear in OPTIONS of the returned config
# Quote: Perhaps they can be passed in a new `extra_options` argument?
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_2() -> None:
    self_after = Env()
    var = 'DJANGO_ENVIRON_TEST_UNSET_DB_URL_XYZ'
    default = 'sqlite://:memory:'
    engine = None
    options_cast = None
    extra_options = {'timeout': 20}
    # The property applies to this input: var == 'DJANGO_ENVIRON_TEST_UNSET_DB_URL_XYZ' and isinstance(default, str) and default.split('://')[0] in Env.DB_SCHEMES and isinstance(extra_options, dict) and len(extra_options) > 0 and engine is None and options_cast is None
    result = self_after.db_url(var=var, default=default, engine=engine, options_cast=options_cast, extra_options={'timeout': 20})
    assert (isinstance(result.get('OPTIONS'), dict) and all(result['OPTIONS'].get(k) == v for k, v in extra_options.items()))
